 * GET /events/v1/events/{eventId}/orders/{orderNumber}?fieldset=TICKETS&fieldset=DETAILS&fieldset=INVOICE  → { order }
 */
export async function fetchOrder(eventId, orderNumber) {
    try {
        const res = await wixRequest(`/events/v1/events/${encodeURIComponent(eventId)}/orders/${encodeURIComponent(orderNumber)}`, {
            method: "GET",
            query: { fieldset: ORDER_FIELDSETS },
